if(p==="customers"){const cursor=u.searchParams.get("cursor")||"";if(cursor.length>2000)return json({error:"Invalid cursor"},400);const r=await sqGet(env,"/v2/customers",{limit:"100",cursor});return json({customers:(r.customers||[]).map(c=>({id:c.id,name:[c.given_name,c.family_name].filter(Boolean).join(" ")||c.company_name||"",email:c.email_address||"",phone:c.phone_number||""})),cursor:r.cursor||null})}
